// ---- 异次元树果袋 #20 ----
// Every berry stack of the holder may be one larger per copy (the game's 2 or 3 -> 3 or 4, with two copies 4 or 5).
// The two mod items that count as berries follow: 文柚大果 and 哆啦A梦树果袋 2 -> 3, with two copies 4.
const hyper = api.item({
  id: 'hyperspace-berry-pouch', name: '异次元树果袋', tier: 'ULTRA', kind: 'held', max: 2, weight: 4, iconFallback: 'berry_pouch',
  description: '携带者的每种树果，最大携带数量+1\n（文柚大果、哆啦A梦树果袋也算）。',
});
api.berryCap(hyper, 1);
api.countsAsBerry(big);
api.countsAsBerry(dora);
// a copy is gone: what no longer fits goes with it (a stack above its limit breaks the game's own checks)
api.on('remove', ev => { if (ev.item === hyper.key && ev.pokemon) B.trimBerries(ev.pokemon); });
api.on('give', ev => { if (ev.item === hyper.key && ev.pokemon) B.trimBerries(ev.pokemon); }); // (nothing to cut: the counts on screen follow)

// ---- 超级巨化卡比兽玩偶 #21 ----
// The teammate eats a berry -> the holder, on the field, gets the same berry half of the time (not above its limit).
const doll = api.item({
  id: 'gmax-snorlax-doll', name: '超级巨化卡比兽玩偶', tier: 'ULTRA', kind: 'held', max: 1, weight: 4, iconFallback: 'leftovers',
  description: '队友吃掉树果时，在场上的携带者有50%概率\n获得一个相同的树果（带满时无法获得）。',
});
const asBerry = { [big.key]: big, [dora.key]: dora }; // the mod items that are eaten as berries
const rolls = { turn: '', n: 0 }; // each berry eaten in a turn gets its own roll
api.on('berryEaten', ev => {
  const eater = ev.pokemon;
  if (!B.isPlayer(eater) || !B.onField(eater)) return;
  const holder = B.ally(eater);
  if (!holder || !doll.heldBy(holder)) return;
  const turn = B.wave() + ':' + B.turn();
  if (rolls.turn !== turn) { rolls.turn = turn; rolls.n = 0; }
  const roll = B.random('doll:' + B.index(eater) + ':' + (ev.item || ev.berry) + ':' + rolls.n++);
  if (roll >= 0.5) return;
  const got = ev.item ? !!asBerry[ev.item] && asBerry[ev.item].give(holder) : B.giveBerry(holder, ev.berry);
  if (got) B.message(B.name(holder) + '的超级巨化卡比兽玩偶\n变出了一个' + ev.name + '！');
});

// ---- 树果种植盆 #30 ----
// One berry when a battle starts, then one for every 3 turns the holder spends acting on the field in that
// battle. Only berries the holder still has room for; none when every kind is full.
const pots = api.item({
  id: 'berry-pots', name: '树果种植盆', tier: 'MASTER', kind: 'held', max: 1, weight: 4, iconFallback: 'sitrus_berry',
  description: '战斗开始时携带者获得1个树果，之后每在场上行动\n3回合再得1个。只给没带满的树果，全满时不给。',
});
// how often each kind comes up: the game's own table for a random berry (文柚果 木子果 苹野果 2/12 each, the other eight share 6/12)
const WEIGHT = [2, 2, 0.75, 0.75, 0.75, 0.75, 0.75, 0.75, 0.75, 0.75, 2];
function plant(p, tag) {
  const room = B.berryRoom(p);
  if (!room.length) return false;
  let r = B.random(tag) * room.reduce((a, t) => a + WEIGHT[t], 0), pick = room[room.length - 1];
  for (const t of room) { r -= WEIGHT[t]; if (r < 0) { pick = t; break; } }
  if (!B.giveBerry(p, pick)) return false;
  B.message(B.name(p) + '的树果种植盆\n结出了一个' + B.berryName(pick) + '！');
  return true;
}
// battle start = the first turn of a wave. state.wave keeps it to once per wave (a wave loaded again from its
// save gets its berry again, because the save is from before it; a save made in the middle does not).
api.onPhase('TurnInitPhase', () => {
  if (B.turn() !== 1) return;
  const wave = B.wave();
  B.party().forEach((p, i) => {
    if (!pots.heldBy(p)) return;
    const st = pots.state(p);
    if (st.wave === wave) return;
    st.wave = wave; st.turns = 0;
    if (!B.fainted(p)) plant(p, 'pots:start:' + i);
  });
}, 'start');
// a turn counts when the holder was on the field as the turn's moves began and is still there when it ends
const acting = new Set();
api.on('turnStart', () => { acting.clear(); for (const p of B.playerField()) if (pots.heldBy(p)) acting.add(p); });
api.on('turnEnd', () => {
  for (const p of B.playerField()) {
    if (!acting.has(p) || !pots.heldBy(p)) continue;
    const st = pots.state(p);
    st.turns = (st.turns || 0) + 1;
    if (st.turns % 3 === 0) plant(p, 'pots:turn:' + B.party().indexOf(p));
  }
  acting.clear();
});
