const tent = api.item({
  id: 'safety-tent', name: '防尘帐篷', tier: 'ULTRA', kind: 'held', max: 1, weight: 4,
  description: '携带者在场时，自己和队友不受沙暴、冰雹的伤害，\n粉末类招式和特性「孢子」对它们无效。',
});
const tentUp = p => !!p && tent.heldBy(p) && B.onField(p);
const covered = p => B.isPlayer(p) && B.onField(p) && (tentUp(p) || tentUp(B.ally(p)));
